"""Compare Python output with committed results generated by pinned R source.

The expected values are never calculated by this library; see golden/README.md.
"""

from pathlib import Path

import pandas as pd
import pytest
from nhs_fixtures import load_ae_attendances

import spc

FIXTURES = Path(__file__).parent / "golden" / "nhsrdatasets"
RULES = {
    "Common Cause": None,
    "Above UCL": "outside_limits",
    "Below LCL": "outside_limits",
    "7 Point Trend (Increasing)": "seven_point_trend",
    "7 Point Trend (Decreasing)": "seven_point_trend",
    "2 in 3 Above CL": "two_in_three_near_limit",
    "2 in 3 Below CL": "two_in_three_near_limit",
    "7 Points Above CL": "seven_point_shift",
    "7 Points Below CL": "seven_point_shift",
}


@pytest.mark.parametrize(
    ("field", "direction", "filename"),
    [
        ("attendances", "neutral", "ae_attendances_rjz_type1_xmr_expected.csv"),
        ("breaches", "decrease", "ae_attendances_rjz_type1_breaches_xmr_expected.csv"),
    ],
)
def test_xmr_matches_pinned_r_reference(
        field,
        direction,
        filename
):
    data = load_ae_attendances()
    data = data[(data["org_code"] == "RJZ") & (data["type"] == "1")].sort_values("period")
    expected = pd.read_csv(FIXTURES / filename).set_index("x")
    assert expected.index.is_unique
    result = spc.chart(
        data,
        kind="xmr",
        options=spc.BaseChartOptions(
            value_field=field,
            date_field="period",
            improvement_direction=direction,
            screen_outliers="single_pass",
        ),
    )
    assert len(result.points) == len(expected) == 36
    assert {str(point.x) for point in result.points} == set(expected.index)
    for point in result.points:
        row = expected.loc[str(point.x)]
        assert point.y == row["y"]  # Also verifies the R and parquet input subsets agree.
        for actual, column in ((point.mean, "mean_col"), (point.ucl, "upl"), (point.lcl, "lpl")):
            assert actual == pytest.approx(row[column], rel=1e-12, abs=1e-9)
        assert point.outside_limits == bool(row["outside_limits"])
        assert point.special_cause_rule == RULES[row["special_cause_type"]]
        assert point.point_type == row["point_type"]
